  "passport.statSkills": { ar:"أدلة مهارية", en:"Skill evidence", tr:"Beceri kanıtları", zh:"技能证据", hi:"कौशल प्रमाण", es:"Evidencia de habilidades", fr:"Preuves de compétences", ur:"مہارت کے شواہد" },
  "passport.statCredentials": { ar:"اعتمادات", en:"Credentials", tr:"Kimlik bilgileri", zh:"认证", hi:"क्रेडेंशियल", es:"Credenciales", fr:"Accréditations", ur:"اسناد" },
  "passport.selectedProjects": { ar:"المشاريع المختارة", en:"Selected projects", tr:"Seçilen projeler", zh:"已选项目", hi:"चयनित परियोजनाएँ", es:"Proyectos seleccionados", fr:"Projets sélectionnés", ur:"منتخب پروجیکٹس" },
  "passport.noProjectsYet": { ar:"لا توجد مشاريع بعد.", en:"No projects yet.", tr:"Henüz proje yok.", zh:"还没有项目。", hi:"अभी तक कोई परियोजना नहीं।", es:"Aún no hay proyectos.", fr:"Aucun projet pour l'instant.", ur:"ابھی تک کوئی پروجیکٹ نہیں۔" },
  "passport.noCredentialsTitle": { ar:"لا توجد Credentials موثقة", en:"No verified Credentials", tr:"Doğrulanmış Credentials yok", zh:"没有已验证的 Credentials", hi:"कोई सत्यापित Credentials नहीं", es:"No hay Credentials verificadas", fr:"Aucun Credentials vérifié", ur:"کوئی تصدیق شدہ Credentials نہیں" },
  "passport.noCredentialsDesc": { ar:"لن نعرض Blockchain stamps أو اعتمادات شكلية. عندما تضيف مؤسسة Credential موثقًا سيظهر مع جهة الإصدار ومستوى التحقق.", en:"We won't show Blockchain stamps or token credentials. When an institution adds a verified Credential, it will appear with its issuer and verification level.", tr:"Blockchain damgaları veya göstermelik kimlik bilgileri göstermeyiz. Bir kurum doğrulanmış bir Credential eklediğinde, düzenleyeni ve doğrulama seviyesiyle görünecektir.", zh:"我们不会展示 Blockchain 印章或形式化认证。当机构添加经过验证的 Credential 时，它将显示其颁发方和验证级别。", hi:"हम Blockchain स्टैम्प या दिखावटी क्रेडेंशियल नहीं दिखाएंगे। जब कोई संस्थान सत्यापित Credential जोड़ेगा, तो वह जारीकर्ता और सत्यापन स्तर के साथ दिखेगा।", es:"No mostraremos sellos de Blockchain ni credenciales simbólicas. Cuando una institución añada un Credential verificado, aparecerá con su emisor y nivel de verificación.", fr:"Nous n'afficherons pas de tampons Blockchain ni d'accréditations de façade. Lorsqu'un établissement ajoute un Credential vérifié, il apparaît avec son émetteur et son niveau de vérification.", ur:"ہم Blockchain اسٹیمپس یا برائے نام اسناد نہیں دکھائیں گے۔ جب کوئی ادارہ تصدیق شدہ Credential شامل کرے گا تو یہ جاری کنندہ اور تصدیق کی سطح کے ساتھ ظاہر ہوگا۔" },
  "passport.portfolioBuilderDesc": { ar:"اختر المشاريع التي يمكن أن تدخل في أي مشاركة مستقبلية. الباقي يبقى خاصًا ولا يدخل في رابط Passport.", en:"Choose the projects that can be included in any future share. The rest stays private and won't be part of the Passport link.", tr:"Gelecekteki paylaşımlara dahil edilebilecek projeleri seçin. Geri kalanı özel kalır ve Passport bağlantısına dahil edilmez.", zh:"选择可以纳入未来分享的项目。其余保持私密，不会包含在 Passport 链接中。", hi:"उन परियोजनाओं को चुनें जिन्हें भविष्य के साझाकरण में शामिल किया जा सके। बाकी निजी रहेंगी और Passport लिंक का हिस्सा नहीं होंगी।", es:"Elige los proyectos que puedan incluirse en un futuro uso compartido. El resto permanece privado y no formará parte del enlace.", fr:"Choisissez les projets pouvant figurer dans un futur partage. Le reste demeure privé et ne fera pas partie du lien.", ur:"وہ پروجیکٹس منتخب کریں جو کسی بھی مستقبل کے اشتراک میں شامل ہو سکیں۔ باقی نجی رہیں گے اور Passport لنک کا حصہ نہیں ہوں گے۔" },
  "passport.selected": { ar:"مختار", en:"Selected", tr:"Seçili", zh:"已选", hi:"चयनित", es:"Seleccionado", fr:"Sélectionné", ur:"منتخب" },
  "passport.private": { ar:"خاص", en:"Private", tr:"Özel", zh:"私密", hi:"निजी", es:"Privado", fr:"Privé", ur:"نجی" },
  "passport.noProjectsToSelect": { ar:"لا توجد مشاريع للاختيار.", en:"No projects to select.", tr:"Seçilecek proje yok.", zh:"没有可选择的项目。", hi:"चुनने के लिए कोई परियोजना नहीं।", es:"No hay proyectos para seleccionar.", fr:"Aucun projet à sélectionner.", ur:"منتخب کرنے کے لیے کوئی پروجیکٹ نہیں۔" },
  "passport.sharesManagement": { ar:"إدارة المشاركات", en:"Share management", tr:"Paylaşım yönetimi", zh:"分享管理", hi:"साझाकरण प्रबंधन", es:"Gestión de uso compartido", fr:"Gestion des partages", ur:"اشتراک کا انتظام" },
  "passport.sharesManagementDesc": { ar:"روابطك قابلة للانتهاء والإلغاء، ويمكن حمايتها بكلمة مرور. عداد المشاهدة لا يكشف هوية الزائر.", en:"Your links can expire and be revoked, and can be protected with a password. The view counter does not reveal the visitor's identity.", tr:"Bağlantılarınızın süresi dolabilir, iptal edilebilir ve parola ile korunabilir. Görüntülenme sayacı ziyaretçinin kimliğini açığa çıkarmaz.", zh:"你的链接可过期并可撤销，还可用密码保护。浏览计数器不会泄露访客身份。", hi:"आपके लिंक समाप्त हो सकते हैं, रद्द किए जा सकते हैं और पासवर्ड से सुरक्षित किए जा सकते हैं। व्यू काउंटर आगंतुक की पहचान उजागर नहीं करता।", es:"Tus enlaces pueden caducar, revocarse y protegerse con contraseña. El contador de vistas no revela la identidad del visitante.", fr:"Vos liens peuvent expirer, être révoqués et protégés par un mot de passe. Le compteur de vues ne révèle pas l'identité du visiteur.", ur:"آپ کے لنکس ختم ہو سکتے ہیں، منسوخ کیے جا سکتے ہیں اور پاس ورڈ سے محفوظ کیے جا سکتے ہیں۔ ویو کاؤنٹر آنے والے کی شناخت ظاہر نہیں کرتا۔" },
  "passport.statusRevoked": { ar:"ملغى", en:"Revoked", tr:"İptal edildi", zh:"已撤销", hi:"रद्द", es:"Revocado", fr:"Révoqué", ur:"منسوخ" },
  "passport.statusExpired": { ar:"منتهي", en:"Expired", tr:"Süresi doldu", zh:"已过期", hi:"समाप्त", es:"Caducado", fr:"Expiré", ur:"میعاد ختم" },
