  "support.subjectPh": { ar:"صف المشكلة بجملة واضحة", en:"Describe the problem in one clear sentence", tr:"Sorunu net bir cümleyle açıklayın", zh:"用一句清晰的话描述问题", hi:"समस्या को एक स्पष्ट वाक्य में बताएँ", es:"Describe el problema en una frase clara", fr:"Décrivez le problème en une phrase claire", ur:"مسئلے کو ایک واضح جملے میں بیان کریں" },
  "support.details": { ar:"التفاصيل", en:"Details", tr:"Ayrıntılar", zh:"详情", hi:"विवरण", es:"Detalles", fr:"Détails", ur:"تفصیلات" },
  "support.detailsPh": { ar:"ما الذي حدث؟ ماذا توقعت أن يحدث؟ لا تضع أسرارًا أو كلمات مرور.", en:"What happened? What did you expect to happen? Do not include secrets or passwords.", tr:"Ne oldu? Ne olmasını bekliyordunuz? Gizli bilgi veya parola eklemeyin.", zh:"发生了什么？你期望发生什么？请勿填写机密信息或密码。", hi:"क्या हुआ? आपने क्या होने की उम्मीद की थी? कोई गोपनीय जानकारी या पासवर्ड न डालें।", es:"¿Qué ocurrió? ¿Qué esperabas que ocurriera? No incluyas secretos ni contraseñas.", fr:"Que s'est-il passé ? À quoi vous attendiez-vous ? N'indiquez pas de secrets ni de mots de passe.", ur:"کیا ہوا؟ آپ کو کیا ہونے کی توقع تھی؟ راز یا پاس ورڈ درج نہ کریں۔" },
  "support.securityNote": { ar:"لا ترسل Passwords أو API keys. الوصول الحساس — إذا لزم لاحقًا — يجب أن يكون مؤقتًا ومدققًا.", en:"Do not send passwords or API keys. Sensitive access — if needed later — must be temporary and audited.", tr:"Parola veya API anahtarı göndermeyin. Hassas erişim — sonradan gerekirse — geçici ve denetlenmiş olmalıdır.", zh:"请勿发送密码或 API 密钥。敏感访问（若日后需要）必须是临时且经过审计的。", hi:"पासवर्ड या API कुंजियाँ न भेजें। संवेदनशील पहुँच — यदि बाद में आवश्यक हो — अस्थायी और ऑडिटेड होनी चाहिए।", es:"No envíes contraseñas ni claves API. El acceso sensible —si se necesita más adelante— debe ser temporal y auditado.", fr:"N'envoyez pas de mots de passe ni de clés API. Tout accès sensible — si nécessaire ultérieurement — doit être temporaire et audité.", ur:"پاس ورڈ یا API کیز نہ بھیجیں۔ حساس رسائی — اگر بعد میں درکار ہو — عارضی اور آڈٹ شدہ ہونی چاہیے۔" },
  "support.submit": { ar:"إرسال التذكرة", en:"Submit ticket", tr:"Talebi gönder", zh:"提交工单", hi:"टिकट सबमिट करें", es:"Enviar ticket", fr:"Envoyer le ticket", ur:"ٹکٹ جمع کریں" },
