  "curric.whatIfDesc": { ar:"اختر مقررًا أو أكثر لإزالته مؤقتًا. لا تتغير أي بيانات؛ النتيجة محاكاة فقط.", en:"Select one or more courses to remove temporarily. No data changes; the result is a simulation only.", tr:"Geçici olarak kaldırmak için bir veya daha fazla ders seçin. Hiçbir veri değişmez; sonuç yalnızca bir simülasyondur.", zh:"选择一门或多门课程临时移除。不会更改任何数据；结果仅为模拟。", hi:"अस्थायी रूप से हटाने के लिए एक या अधिक कोर्स चुनें। कोई डेटा नहीं बदलता; परिणाम केवल एक सिमुलेशन है।", es:"Selecciona uno o más cursos para eliminar temporalmente. No se cambian datos; el resultado es solo una simulación.", fr:"Sélectionnez un ou plusieurs cours à retirer temporairement. Aucune donnée n'est modifiée ; le résultat est une simulation seulement.", ur:"عارضی طور پر ہٹانے کے لیے ایک یا زیادہ کورسز منتخب کریں۔ کوئی ڈیٹا نہیں بدلتا؛ نتیجہ صرف ایک سمولیشن ہے۔" },
  "curric.whatIfTitle": { ar:"ماذا لو غيّرنا المنهج؟", en:"What if we changed the curriculum?", tr:"Ya müfredatı değiştirseydik?", zh:"如果我们更改课程会怎样？", hi:"अगर हम पाठ्यक्रम बदलें तो क्या होगा?", es:"¿Y si cambiáramos el currículo?", fr:"Et si nous changions le programme ?", ur:"اگر ہم نصاب بدل دیں تو کیا ہوگا؟" },
  "curric.workloadTitle": { ar:"ضغط التكليفات عبر الفصول", en:"Assignment load across terms", tr:"Dönemler boyunca ödev yükü", zh:"各学期作业负荷", hi:"सत्रों में असाइनमेंट भार", es:"Carga de tareas por período", fr:"Charge de travail par semestre", ur:"سمسٹرز میں اسائنمنٹ کا بوجھ" },
  "evid.addDesc": { ar:"كل عنصر يبقى Unverified حتى يتحقق منه المستخدم أو المؤسسة. لا يحوّل الرابط إلى “مصدر موثوق” تلقائيًا.", en:"Every item stays Unverified until the user or institution verifies it. A link is not turned into a “trusted source” automatically.", tr:"Her öğe, kullanıcı veya kurum doğrulayana kadar Unverified kalır. Bir bağlantı otomatik olarak “güvenilir kaynağa” dönüşmez.", zh:"每个条目在用户或机构验证之前都保持 Unverified 状态。链接不会被自动变成“可信来源”。", hi:"हर आइटम तब तक Unverified रहता है जब तक उपयोगकर्ता या संस्थान उसे सत्यापित न कर दे। कोई लिंक अपने आप “विश्वसनीय स्रोत” नहीं बन जाता।", es:"Cada elemento permanece Unverified hasta que el usuario o la institución lo verifique. Un enlace no se convierte en “fuente confiable” automáticamente.", fr:"Chaque élément reste Unverified jusqu'à ce que l'utilisateur ou l'établissement le vérifie. Un lien ne devient pas automatiquement une “source fiable”.", ur:"ہر آئٹم اس وقت تک Unverified رہتا ہے جب تک صارف یا ادارہ اس کی تصدیق نہ کرے۔ کوئی لنک خود بخود “قابلِ اعتماد ماخذ” نہیں بن جاتا۔" },
  "evid.addTitle": { ar:"أضف دليلًا أو مصدرًا", en:"Add evidence or a source", tr:"Kanıt veya kaynak ekle", zh:"添加证据或来源", hi:"प्रमाण या स्रोत जोड़ें", es:"Añade una evidencia o fuente", fr:"Ajouter une preuve ou une source", ur:"ثبوت یا ماخذ شامل کریں" },
  "evid.advancedLink": { ar:"الربط المتقدم", en:"Advanced linking", tr:"Gelişmiş bağlantı", zh:"高级关联", hi:"उन्नत लिंकिंग", es:"Enlace avanzado", fr:"Liaison avancée", ur:"اعلیٰ درجے کی لنکنگ" },
  "evid.advancedLinkHint": { ar:"اختياري · يبني Trust Graph صريحًا", en:"Optional · builds an explicit Trust Graph", tr:"İsteğe bağlı · açık bir Trust Graph oluşturur", zh:"可选 · 构建显式的 Trust Graph", hi:"वैकल्पिक · एक स्पष्ट Trust Graph बनाता है", es:"Opcional · construye un Trust Graph explícito", fr:"Facultatif · construit un Trust Graph explicite", ur:"اختیاری · واضح Trust Graph بناتا ہے" },
