  "home.ctaInstitutions": { ar:"دخول المؤسسات", en:"Institutions login", tr:"Kurum girişi", zh:"机构登录", hi:"संस्थान लॉगिन", es:"Acceso institucional", fr:"Connexion institutions", ur:"اداروں کا لاگ ان" },
  "home.ctaStart": { ar:"ابدأ بتكليفك", en:"Start with your assignment", tr:"Ödevinizle başlayın", zh:"从你的作业开始", hi:"अपने असाइनमेंट से शुरू करें", es:"Empieza con tu tarea", fr:"Commencez par votre devoir", ur:"اپنی اسائنمنٹ سے شروع کریں" },
  "home.featureCompilerText": { ar:"يستخرج المتطلبات والمخرجات والموعد والتنسيق والسياسة بدون اختراع الناقص.", en:"Extracts the requirements, deliverables, deadline, format, and policy without inventing what's missing.", tr:"Gereksinimleri, teslimatları, son tarihi, biçimi ve politikayı eksik olanı uydurmadan çıkarır.", zh:"提取要求、交付物、截止日期、格式和政策，不会编造缺失的内容。", hi:"आवश्यकताएँ, डिलिवरेबल्स, समय-सीमा, प्रारूप और नीति निकालता है, बिना छूटी हुई चीज़ों को गढ़े।", es:"Extrae los requisitos, entregables, fecha límite, formato y política sin inventar lo que falta.", fr:"Extrait les exigences, livrables, échéance, format et politique sans inventer ce qui manque.", ur:"تقاضے، ڈیلیوریبلز، آخری تاریخ، فارمیٹ اور پالیسی نکالتا ہے، بغیر گمشدہ چیزیں گھڑے۔" },
  "home.featurePolicyText": { ar:"AI لا يتجاوز سياسة المقرر؛ المناطق المحظورة تتحول إلى تعلم وتغذية راجعة.", en:"AI never exceeds the course policy; restricted areas turn into learning and feedback.", tr:"Yapay zeka ders politikasını asla aşmaz; kısıtlı alanlar öğrenmeye ve geri bildirime dönüşür.", zh:"AI 绝不逾越课程政策；受限区域转化为学习与反馈。", hi:"AI कभी कोर्स नीति से आगे नहीं जाता; प्रतिबंधित क्षेत्र सीखने और फ़ीडबैक में बदल जाते हैं।", es:"La IA nunca excede la política del curso; las áreas restringidas se convierten en aprendizaje y retroalimentación.", fr:"L'IA ne dépasse jamais la politique du cours ; les zones restreintes se transforment en apprentissage et retour.", ur:"AI کبھی کورس پالیسی سے تجاوز نہیں کرتا؛ ممنوعہ علاقے سیکھنے اور فیڈ بیک میں بدل جاتے ہیں۔" },
  "home.featureProofText": { ar:"المهارة ترتبط بدليل ومشروع وتاريخ، لا بنسبة نفسية أو Badge بلا معنى.", en:"A skill is tied to evidence, a project, and a date — not to a made-up percentage or a meaningless badge.", tr:"Bir beceri; kanıta, projeye ve tarihe bağlıdır — uydurma bir yüzdeye ya da anlamsız bir rozete değil.", zh:"技能与证据、项目和日期挂钩，而非凭空捏造的百分比或毫无意义的徽章。", hi:"कौशल प्रमाण, एक प्रोजेक्ट और एक तिथि से जुड़ा होता है — किसी मनगढ़ंत प्रतिशत या अर्थहीन बैज से नहीं।", es:"Una habilidad se vincula a evidencia, un proyecto y una fecha, no a un porcentaje inventado ni a una insignia sin sentido.", fr:"Une compétence est liée à une preuve, un projet et une date — pas à un pourcentage inventé ou à un badge sans valeur.", ur:"مہارت ثبوت، پروجیکٹ اور تاریخ سے جڑی ہوتی ہے — کسی من گھڑت فیصد یا بےمعنی بیج سے نہیں۔" },
  "home.featureTwinText": { ar:"يربط المشروع والمخرجات والـRubric والمهام في بنية واحدة قابلة للتتبع.", en:"Links the project, deliverables, rubric, and tasks into a single traceable structure.", tr:"Projeyi, teslimatları, rubriği ve görevleri izlenebilir tek bir yapıda birleştirir.", zh:"将项目、交付物、评分标准和任务链接为一个可追溯的结构。", hi:"प्रोजेक्ट, डिलिवरेबल्स, रुब्रिक और कार्यों को एक ट्रेस करने योग्य संरचना में जोड़ता है।", es:"Vincula el proyecto, los entregables, la rúbrica y las tareas en una sola estructura rastreable.", fr:"Relie le projet, les livrables, la grille et les tâches en une seule structure traçable.", ur:"پروجیکٹ، ڈیلیوریبلز، روبرک اور کاموں کو ایک قابلِ سراغ ڈھانچے میں جوڑتا ہے۔" },
  "home.footerAccessibility": { ar:"الوصول", en:"Accessibility", tr:"Erişilebilirlik", zh:"无障碍", hi:"सुगम्यता", es:"Accesibilidad", fr:"Accessibilité", ur:"رسائی" },
  "home.footerIntegrity": { ar:"النزاهة الأكاديمية", en:"Academic integrity", tr:"Akademik dürüstlük", zh:"学术诚信", hi:"शैक्षणिक अखंडता", es:"Integridad académica", fr:"Intégrité académique", ur:"علمی دیانت" },
