  "passport.credentials": { ar:"اعتمادات", en:"Credentials", tr:"Kimlik bilgileri", zh:"证书", hi:"क्रेडेंशियल", es:"Credenciales", fr:"Accréditations", ur:"اسناد" },
  "passport.educationUnspecified": { ar:"المرحلة التعليمية غير محددة", en:"Education level unspecified", tr:"Eğitim düzeyi belirtilmemiş", zh:"未指定教育阶段", hi:"शिक्षा स्तर निर्दिष्ट नहीं", es:"Nivel educativo no especificado", fr:"Niveau d'études non précisé", ur:"تعلیمی سطح غیر متعین" },
  "passport.expired": { ar:"منتهي", en:"Expired", tr:"Süresi doldu", zh:"已过期", hi:"समाप्त", es:"Caducado", fr:"Expiré", ur:"ختم شدہ" },
  "passport.headerDesc": { ar:"سجل أدلة تختار أنت ما يُشارك منه. لا توجد شارات “موثقة” بلا جهة ومعنى، ولا بيانات عامة افتراضيًا.", en:"A record of evidence where you choose what is shared. No “verified” badges without an issuer and meaning, and no public data by default.", tr:"Neyin paylaşılacağını sizin seçtiğiniz bir kanıt kaydı. Kaynağı ve anlamı olmayan “doğrulanmış” rozetler yok ve varsayılan olarak herkese açık veri yok.", zh:"一份由您决定分享内容的证据记录。没有缺乏来源与意义的“已验证”徽章，默认也不公开任何数据。", hi:"साक्ष्य का एक रिकॉर्ड जहाँ आप चुनते हैं कि क्या साझा हो। बिना जारीकर्ता और अर्थ के कोई “सत्यापित” बैज नहीं, और डिफ़ॉल्ट रूप से कोई सार्वजनिक डेटा नहीं।", es:"Un registro de evidencias donde tú eliges qué se comparte. Sin insignias “verificadas” sin emisor ni significado, y sin datos públicos de forma predeterminada.", fr:"Un registre de preuves où vous choisissez ce qui est partagé. Pas de badges « vérifiés » sans émetteur ni signification, et aucune donnée publique par défaut.", ur:"شواہد کا ایک ریکارڈ جہاں آپ خود طے کرتے ہیں کہ کیا شیئر ہو۔ بغیر جاری کنندہ اور معنی کے کوئی “تصدیق شدہ” بیج نہیں، اور بطورِ ڈیفالٹ کوئی عوامی ڈیٹا نہیں۔" },
  "passport.manageShares": { ar:"إدارة المشاركات", en:"Manage shares", tr:"Paylaşımları yönet", zh:"管理分享", hi:"साझाकरण प्रबंधित करें", es:"Gestionar comparticiones", fr:"Gérer les partages", ur:"اشتراکات کا انتظام" },
  "passport.noProjects": { ar:"لا توجد مشاريع بعد.", en:"No projects yet.", tr:"Henüz proje yok.", zh:"暂无项目。", hi:"अभी तक कोई परियोजना नहीं।", es:"Aún no hay proyectos.", fr:"Aucun projet pour l'instant.", ur:"ابھی کوئی پروجیکٹ نہیں۔" },
  "passport.noShares": { ar:"لم تنشئ روابط مشاركة بعد.", en:"You haven't created any share links yet.", tr:"Henüz paylaşım bağlantısı oluşturmadınız.", zh:"您尚未创建任何分享链接。", hi:"आपने अभी तक कोई साझा लिंक नहीं बनाया है।", es:"Aún no has creado ningún enlace para compartir.", fr:"Vous n'avez pas encore créé de lien de partage.", ur:"آپ نے ابھی تک کوئی اشتراک لنک نہیں بنایا۔" },
  "passport.portfolioDesc": { ar:"اختر المشاريع التي يمكن أن تدخل في أي مشاركة مستقبلية. الباقي يبقى خاصًا ولا يدخل في رابط Passport.", en:"Choose the projects that may be included in any future share. The rest stays private and is not included in the Passport link.", tr:"Gelecekteki herhangi bir paylaşıma dahil edilebilecek projeleri seçin. Geri kalanı özel kalır ve Passport bağlantısına dahil edilmez.", zh:"选择可纳入任何未来分享的项目。其余项目保持私密，不会包含在 Passport 链接中。", hi:"वे परियोजनाएँ चुनें जो किसी भी भविष्य के साझाकरण में शामिल हो सकती हैं। बाकी निजी रहती हैं और Passport लिंक में शामिल नहीं होतीं।", es:"Elige los proyectos que puedan incluirse en cualquier futura compartición. El resto permanece privado y no se incluye en el enlace del Passport.", fr:"Choisissez les projets qui pourront être inclus dans tout futur partage. Le reste reste privé et n'est pas inclus dans le lien Passport.", ur:"وہ پروجیکٹس منتخب کریں جو کسی بھی مستقبل کے اشتراک میں شامل ہو سکتے ہیں۔ باقی نجی رہتے ہیں اور Passport لنک میں شامل نہیں ہوتے۔" },
  "passport.projects": { ar:"مشاريع", en:"Projects", tr:"Projeler", zh:"项目", hi:"परियोजनाएँ", es:"Proyectos", fr:"Projets", ur:"پروجیکٹس" },
  "passport.revoked": { ar:"ملغى", en:"Revoked", tr:"İptal edildi", zh:"已撤销", hi:"रद्द", es:"Revocado", fr:"Révoqué", ur:"منسوخ" },
  "passport.shareFailed": { ar:"تعذر إنشاء الرابط", en:"Could not create the link", tr:"Bağlantı oluşturulamadı", zh:"无法创建链接", hi:"लिंक नहीं बनाया जा सका", es:"No se pudo crear el enlace", fr:"Impossible de créer le lien", ur:"لنک نہیں بنایا جا سکا" },
  "passport.sharesDesc": { ar:"روابطك قابلة للانتهاء والإلغاء، ويمكن حمايتها بكلمة مرور. عداد المشاهدة لا يكشف هوية الزائر.", en:"Your links can expire and be revoked, and can be protected with a password. The view counter does not reveal the visitor's identity.", tr:"Bağlantılarınızın süresi dolabilir ve iptal edilebilir, ayrıca parolayla korunabilir. Görüntüleme sayacı ziyaretçinin kimliğini açığa çıkarmaz.", zh:"您的链接可设置过期并可撤销，还可用密码保护。浏览计数器不会泄露访客身份。", hi:"आपके लिंक समाप्त हो सकते हैं और रद्द किए जा सकते हैं, और पासवर्ड से सुरक्षित किए जा सकते हैं। व्यू काउंटर आगंतुक की पहचान उजागर नहीं करता।", es:"Tus enlaces pueden caducar y revocarse, y pueden protegerse con una contraseña. El contador de vistas no revela la identidad del visitante.", fr:"Vos liens peuvent expirer et être révoqués, et peuvent être protégés par un mot de passe. Le compteur de vues ne révèle pas l'identité du visiteur.", ur:"آپ کے لنکس ختم ہو سکتے ہیں اور منسوخ کیے جا سکتے ہیں، اور انہیں پاس ورڈ سے محفوظ کیا جا سکتا ہے۔ ویو کاؤنٹر زائر کی شناخت ظاہر نہیں کرتا۔" },
  "passport.skillEvidence": { ar:"أدلة مهارية", en:"Skill evidence", tr:"Beceri kanıtları", zh:"技能证据", hi:"कौशल साक्ष्य", es:"Evidencias de habilidades", fr:"Preuves de compétences", ur:"مہارت کے شواہد" },
