  "plat.cat.network": { ar:"الشبكة الخارجية", en:"External Network", tr:"Dış Ağ", zh:"外部网络", hi:"बाहरी नेटवर्क", es:"Red Externa", fr:"Réseau Externe", ur:"بیرونی نیٹ ورک" },
  "plat.cat.trust": { ar:"الثقة والأمن", en:"Trust & Security", tr:"Güven ve Güvenlik", zh:"信任与安全", hi:"विश्वास और सुरक्षा", es:"Confianza y Seguridad", fr:"Confiance et Sécurité", ur:"اعتماد و سلامتی" },
  "plat.desc": { ar:"طبقة إدارة حقيقية للحوكمة والمؤسسات والاعتماد والشبكات والتكاملات ودورة البيانات. كل سجل Tenant-scoped، versioned، وعملياته الحساسة مدققة.", en:"A real management layer for governance, institutions, accreditation, networks, integrations, and the data lifecycle. Every record is Tenant-scoped, versioned, and its sensitive operations are audited.", tr:"Yönetişim, kurumlar, akreditasyon, ağlar, entegrasyonlar ve veri yaşam döngüsü için gerçek bir yönetim katmanı. Her kayıt Tenant kapsamlı, sürümlenmiş ve hassas işlemleri denetlenir.", zh:"面向治理、机构、认证、网络、集成和数据生命周期的真实管理层。每条记录都是 Tenant-scoped、版本化的，其敏感操作均经过审计。", hi:"अभिशासन, संस्थानों, प्रत्यायन, नेटवर्क, एकीकरण और डेटा जीवनचक्र के लिए एक वास्तविक प्रबंधन परत। हर रिकॉर्ड Tenant-scoped, versioned है और उसके संवेदनशील ऑपरेशन ऑडिट किए जाते हैं।", es:"Una capa de gestión real para gobernanza, instituciones, acreditación, redes, integraciones y el ciclo de vida de datos. Cada registro es Tenant-scoped, versionado y sus operaciones sensibles se auditan.", fr:"Une véritable couche de gestion pour la gouvernance, les institutions, l'accréditation, les réseaux, les intégrations et le cycle de vie des données. Chaque enregistrement est Tenant-scoped, versionné, et ses opérations sensibles sont auditées.", ur:"گورننس، اداروں، منظوری، نیٹ ورکس، انضمامات اور ڈیٹا لائف سائیکل کے لیے ایک حقیقی انتظامی پرت۔ ہر ریکارڈ Tenant-scoped، versioned ہے اور اس کے حساس عملیات کا آڈٹ ہوتا ہے۔" },
  "plat.edit": { ar:"تعديل", en:"Edit", tr:"Düzenle", zh:"编辑", hi:"संपादित करें", es:"Editar", fr:"Modifier", ur:"ترمیم" },
