  "plat.noRecordsHint": { ar:"ابدأ بإضافة سجل حقيقي لهذا المورد، أو اتركه فارغًا إن لم تكن المؤسسة تحتاجه.", en:"Start by adding a real record for this resource, or leave it empty if the institution does not need it.", tr:"Bu kaynak için gerçek bir kayıt ekleyerek başlayın veya kurum ihtiyaç duymuyorsa boş bırakın.", zh:"先为该资源添加一条真实记录，若机构不需要则留空。", hi:"इस संसाधन के लिए एक वास्तविक रिकॉर्ड जोड़कर शुरू करें, या यदि संस्थान को इसकी आवश्यकता नहीं है तो इसे खाली छोड़ दें।", es:"Comienza añadiendo un registro real para este recurso, o déjalo vacío si la institución no lo necesita.", fr:"Commencez par ajouter un enregistrement réel pour cette ressource, ou laissez-la vide si l'institution n'en a pas besoin.", ur:"اس وسیلے کے لیے ایک حقیقی ریکارڈ شامل کر کے شروع کریں، یا اگر ادارے کو اس کی ضرورت نہیں تو اسے خالی چھوڑ دیں۔" },
  "plat.prompt.changeReason": { ar:"اكتب سبب التغيير ليُسجل في Audit Log:", en:"Enter the reason for the change to log in the Audit Log:", tr:"Denetim Günlüğüne kaydedilmek üzere değişiklik nedenini yazın:", zh:"输入更改原因以记录到审计日志：", hi:"ऑडिट लॉग में दर्ज करने के लिए बदलाव का कारण लिखें:", es:"Escribe el motivo del cambio para registrarlo en el Audit Log:", fr:"Saisissez la raison du changement à consigner dans l'Audit Log :", ur:"Audit Log میں درج کرنے کے لیے تبدیلی کی وجہ لکھیں:" },
  "plat.prompt.deleteReason": { ar:"سبب الحذف المنطقي (لن يُمسح السجل نهائيًا):", en:"Reason for soft delete (the record will not be permanently erased):", tr:"Mantıksal silme nedeni (kayıt kalıcı olarak silinmeyecek):", zh:"逻辑删除的原因（记录不会被永久删除）：", hi:"सॉफ्ट डिलीट का कारण (रिकॉर्ड स्थायी रूप से नहीं मिटेगा):", es:"Motivo de la eliminación lógica (el registro no se borrará permanentemente):", fr:"Raison de la suppression logique (l'enregistrement ne sera pas effacé définitivement) :", ur:"منطقی حذف کی وجہ (ریکارڈ مستقل طور پر نہیں مٹے گا):" },
