  "prof.descriptionPh": { ar:"وصف موجز للمقرر…", en:"A brief course description…", tr:"Kısa bir ders açıklaması…", zh:"简短的课程描述…", hi:"संक्षिप्त कोर्स विवरण…", es:"Una breve descripción del curso…", fr:"Une brève description du cours…", ur:"مختصر کورس تفصیل…" },
  "prof.emptyTitle": { ar:"ابدأ بأول مقرر", en:"Start with your first course", tr:"İlk dersinle başla", zh:"从您的第一门课程开始", hi:"अपने पहले कोर्स से शुरू करें", es:"Empieza con tu primer curso", fr:"Commencez par votre premier cours", ur:"اپنے پہلے کورس سے آغاز کریں" },
