  "review.action.workspace.artifact.delete": { ar:"حذف عنصر Workspace", en:"Delete Workspace item", tr:"Workspace öğesini sil", zh:"删除 Workspace 项", hi:"Workspace आइटम हटाएँ", es:"Eliminar elemento de Workspace", fr:"Supprimer l'élément Workspace", ur:"Workspace آئٹم حذف کریں" },
  "review.action.workspace.artifact.restore": { ar:"استرجاع إصدار Workspace", en:"Restore Workspace version", tr:"Workspace sürümünü geri yükle", zh:"恢复 Workspace 版本", hi:"Workspace संस्करण पुनर्स्थापित करें", es:"Restaurar versión de Workspace", fr:"Restaurer la version Workspace", ur:"Workspace ورژن بحال کریں" },
