  "supcon.title": { ar:"صندوق الدعم", en:"Support Inbox", tr:"Destek Kutusu", zh:"支持收件箱", hi:"सहायता इनबॉक्स", es:"Bandeja de soporte", fr:"Boîte de support", ur:"سپورٹ ان باکس" },
  "team.active": { ar:"نشط", en:"active", tr:"etkin", zh:"活跃", hi:"सक्रिय", es:"activo", fr:"actif", ur:"فعال" },
  "team.contributionDesc": { ar:"Evidence، لا حكم آلي على “من عمل أكثر”. الأرقام التالية تعدّ الأحداث المسجلة فقط.", en:"Evidence, not an automated verdict on “who did more”. The numbers below only count logged events.", tr:"Kanıt, “kim daha çok yaptı” konusunda otomatik bir karar değil. Aşağıdaki sayılar yalnızca kaydedilen olayları sayar.", zh:"这是证据，而非对“谁做得更多”的自动判定。下面的数字仅统计已记录的事件。", hi:"प्रमाण, “किसने अधिक किया” पर स्वचालित निर्णय नहीं। नीचे की संख्याएँ केवल दर्ज घटनाओं की गिनती करती हैं।", es:"Evidencia, no un veredicto automático sobre “quién hizo más”. Los números siguientes solo cuentan eventos registrados.", fr:"Des preuves, pas un verdict automatique sur « qui a fait le plus ». Les chiffres ci-dessous ne comptent que les événements journalisés.", ur:"ثبوت، نہ کہ “کس نے زیادہ کیا” پر خودکار فیصلہ۔ نیچے دیے گئے اعداد صرف ریکارڈ شدہ واقعات گنتے ہیں۔" },
  "team.individualNotice": { ar:"التكليف مصنف كعمل فردي؛ AcademicOS لا يفتح تعاون أعضاء يمكنهم تعديل المشروع لأن ذلك قد يخالف متطلبات المقرر.", en:"The assignment is classified as individual work; AcademicOS does not enable member collaboration that could edit the project, because that may violate course requirements.", tr:"Ödev bireysel çalışma olarak sınıflandırılmıştır; AcademicOS, ders gereksinimlerini ihlal edebileceğinden projeyi düzenleyebilecek üye işbirliğini açmaz.", zh:"该作业被归类为个人作业；AcademicOS 不开放可编辑项目的成员协作，因为这可能违反课程要求。", hi:"यह असाइनमेंट व्यक्तिगत कार्य के रूप में वर्गीकृत है; AcademicOS ऐसे सदस्य सहयोग को सक्षम नहीं करता जो प्रोजेक्ट संपादित कर सके, क्योंकि यह कोर्स आवश्यकताओं का उल्लंघन कर सकता है।", es:"La tarea está clasificada como trabajo individual; AcademicOS no habilita la colaboración de miembros que puedan editar el proyecto, porque podría infringir los requisitos del curso.", fr:"Le travail est classé comme individuel ; AcademicOS n'active pas la collaboration de membres pouvant modifier le projet, car cela pourrait enfreindre les exigences du cours.", ur:"یہ اسائنمنٹ انفرادی کام کے طور پر درجہ بند ہے؛ AcademicOS ایسے رکنی تعاون کو فعال نہیں کرتا جو پروجیکٹ میں ترمیم کر سکے، کیونکہ یہ کورس کے تقاضوں کی خلاف ورزی ہو سکتی ہے۔" },
  "team.invite": { ar:"دعوة", en:"Invite", tr:"Davet et", zh:"邀请", hi:"आमंत्रित करें", es:"Invitar", fr:"Inviter", ur:"دعوت دیں" },
  "team.inviteHint": { ar:"الدعوات الداخلية تعمل للحسابات الموجودة في نفس الـTenant. إرسال البريد الخارجي يحتاج Email Provider منفصل.", en:"Internal invitations work for accounts within the same Tenant. Sending external email requires a separate Email Provider.", tr:"Dahili davetler aynı Tenant içindeki hesaplar için çalışır. Harici e-posta göndermek için ayrı bir Email Provider gerekir.", zh:"内部邀请适用于同一 Tenant 内的账户。发送外部邮件需要单独的 Email Provider。", hi:"आंतरिक निमंत्रण उसी Tenant के भीतर के खातों के लिए काम करते हैं। बाहरी ईमेल भेजने के लिए अलग Email Provider चाहिए।", es:"Las invitaciones internas funcionan para cuentas dentro del mismo Tenant. Enviar correo externo requiere un Email Provider aparte.", fr:"Les invitations internes fonctionnent pour les comptes du même Tenant. L'envoi d'e-mails externes nécessite un Email Provider distinct.", ur:"اندرونی دعوتیں اسی Tenant کے اندر موجود اکاؤنٹس کے لیے کام کرتی ہیں۔ بیرونی ای میل بھیجنے کے لیے علیحدہ Email Provider درکار ہے۔" },
  "team.inviteLabel": { ar:"دعوة عضو عبر البريد", en:"Invite a member by email", tr:"E-posta ile üye davet et", zh:"通过邮箱邀请成员", hi:"ईमेल द्वारा सदस्य आमंत्रित करें", es:"Invitar a un miembro por correo", fr:"Inviter un membre par e-mail", ur:"ای میل کے ذریعے رکن کو مدعو کریں" },
