  "team.presenceTitle": { ar:"الموجودون الآن", en:"Currently online", tr:"Şu anda çevrimiçi", zh:"当前在线", hi:"अभी ऑनलाइन", es:"En línea ahora", fr:"En ligne actuellement", ur:"ابھی آن لائن" },
  "team.revokeMembership": { ar:"إلغاء العضوية", en:"Revoke membership", tr:"Üyeliği iptal et", zh:"撤销成员资格", hi:"सदस्यता रद्द करें", es:"Revocar membresía", fr:"Révoquer l'adhésion", ur:"رکنیت منسوخ کریں" },
  "team.roleLeader": { ar:"قائد", en:"Leader", tr:"Lider", zh:"组长", hi:"नेता", es:"Líder", fr:"Responsable", ur:"قائد" },
  "team.roleMember": { ar:"عضو", en:"Member", tr:"Üye", zh:"成员", hi:"सदस्य", es:"Miembro", fr:"Membre", ur:"رکن" },
  "team.studioDesc": { ar:"تعاون محفوظ داخل نفس الـTenant. قبول الدعوة مطلوب قبل منح الوصول، والمالك يبقى صاحب الإجراءات الحساسة.", en:"Collaboration kept within the same Tenant. Accepting the invitation is required before access is granted, and the owner retains the sensitive actions.", tr:"İşbirliği aynı Tenant içinde tutulur. Erişim verilmeden önce davetin kabul edilmesi gerekir ve hassas işlemler sahibinde kalır.", zh:"协作保持在同一 Tenant 内。授予访问权限前须接受邀请，敏感操作仍归所有者。", hi:"सहयोग उसी Tenant के भीतर रखा जाता है। पहुँच देने से पहले निमंत्रण स्वीकार करना आवश्यक है, और संवेदनशील कार्य स्वामी के पास रहते हैं।", es:"La colaboración se mantiene dentro del mismo Tenant. Aceptar la invitación es obligatorio antes de conceder acceso, y el propietario conserva las acciones sensibles.", fr:"La collaboration reste au sein du même Tenant. L'acceptation de l'invitation est requise avant l'octroi de l'accès, et le propriétaire conserve les actions sensibles.", ur:"تعاون اسی Tenant کے اندر رکھا جاتا ہے۔ رسائی دینے سے پہلے دعوت قبول کرنا ضروری ہے، اور حساس اقدامات مالک کے پاس رہتے ہیں۔" },
