  "users.colUser": { ar:"المستخدم", en:"User", tr:"Kullanıcı", zh:"用户", hi:"उपयोगकर्ता", es:"Usuario", fr:"Utilisateur", ur:"صارف" },
  "users.confirmSave": { ar:"تأكيد وتسجيل", en:"Confirm and log", tr:"Onayla ve kaydet", zh:"确认并记录", hi:"पुष्टि करें और लॉग करें", es:"Confirmar y registrar", fr:"Confirmer et journaliser", ur:"تصدیق کریں اور لاگ کریں" },
  "users.confirmSensitive": { ar:"تأكيد إجراء حساس", en:"Confirm a sensitive action", tr:"Hassas bir işlemi onayla", zh:"确认敏感操作", hi:"संवेदनशील कार्रवाई की पुष्टि करें", es:"Confirmar una acción sensible", fr:"Confirmer une action sensible", ur:"حساس کارروائی کی تصدیق کریں" },
  "users.emailUnverified": { ar:"البريد غير موثق", en:"Email not verified", tr:"E-posta doğrulanmadı", zh:"邮箱未验证", hi:"ईमेल असत्यापित", es:"Correo no verificado", fr:"E-mail non vérifié", ur:"ای میل غیر تصدیق شدہ" },
  "users.emailVerified": { ar:"بريد موثق", en:"Email verified", tr:"E-posta doğrulandı", zh:"邮箱已验证", hi:"ईमेल सत्यापित", es:"Correo verificado", fr:"E-mail vérifié", ur:"ای میل تصدیق شدہ" },
  "users.loadNext": { ar:"تحميل الدفعة التالية", en:"Load next batch", tr:"Sonraki grubu yükle", zh:"加载下一批", hi:"अगला बैच लोड करें", es:"Cargar el siguiente lote", fr:"Charger le lot suivant", ur:"اگلا بیچ لوڈ کریں" },
  "users.noName": { ar:"بدون اسم", en:"No name", tr:"İsimsiz", zh:"无姓名", hi:"नाम नहीं", es:"Sin nombre", fr:"Sans nom", ur:"بغیر نام" },
  "users.noResults": { ar:"لا توجد نتائج في النطاق الحالي.", en:"No results in the current scope.", tr:"Mevcut kapsamda sonuç yok.", zh:"当前范围内没有结果。", hi:"वर्तमान स्कोप में कोई परिणाम नहीं।", es:"No hay resultados en el alcance actual.", fr:"Aucun résultat dans le périmètre actuel.", ur:"موجودہ دائرہ کار میں کوئی نتیجہ نہیں۔" },
  "users.pageDesc": { ar:"إدارة فعلية لـFirebase Auth داخل نطاق المؤسسة الحالي. لا كلمات مرور، لا ترقية Root من الواجهة، وكل تغيير صلاحية أو تعطيل يحتاج سببًا ويسجل في Audit Log.", en:"Real management of Firebase Auth within the current tenant scope. No passwords, no root promotion from the UI, and every role change or disable requires a reason and is recorded in the Audit Log.", tr:"Mevcut kiracı kapsamında gerçek Firebase Auth yönetimi. Parola yok, arayüzden Root yükseltme yok; her rol değişikliği veya devre dışı bırakma bir gerekçe gerektirir ve Denetim Günlüğüne kaydedilir.", zh:"在当前租户范围内对 Firebase Auth 进行实际管理。无密码、界面不可提升 Root，每次角色变更或停用都需要理由并记录到审计日志。", hi:"वर्तमान टेनेंट स्कोप में Firebase Auth का वास्तविक प्रबंधन। कोई पासवर्ड नहीं, UI से कोई Root प्रमोशन नहीं, और हर भूमिका बदलाव या निष्क्रिय करने के लिए कारण आवश्यक है और Audit Log में दर्ज होता है।", es:"Gestión real de Firebase Auth dentro del alcance del tenant actual. Sin contraseñas, sin promoción a Root desde la interfaz, y cada cambio de rol o desactivación requiere un motivo y se registra en el Audit Log.", fr:"Gestion réelle de Firebase Auth dans le périmètre du locataire actuel. Aucun mot de passe, aucune promotion Root depuis l'interface, et chaque changement de rôle ou désactivation nécessite un motif et est consigné dans l'Audit Log.", ur:"موجودہ ٹیننٹ دائرہ کار میں Firebase Auth کا حقیقی انتظام۔ کوئی پاس ورڈ نہیں، UI سے کوئی Root ترقی نہیں، اور ہر کردار کی تبدیلی یا غیر فعالی کے لیے وجہ درکار ہے اور Audit Log میں درج ہوتی ہے۔" },
  "users.pageTitle": { ar:"إدارة المستخدمين", en:"User Management", tr:"Kullanıcı Yönetimi", zh:"用户管理", hi:"उपयोगकर्ता प्रबंधन", es:"Gestión de usuarios", fr:"Gestion des utilisateurs", ur:"صارف انتظام" },
