  "landing.priceHeadline": { ar:"ابدأ مجاناً. المشروع الكامل من {price}.", en:"Start free. Full projects from {price}.", tr:"Ücretsiz başla. Tam proje {price}’dan.", zh:"免费开始。完整项目 {price} 起。", hi:"मुफ़्त शुरू करें। पूरा प्रोजेक्ट {price} से।", es:"Empieza gratis. Proyecto completo desde {price}.", fr:"Commencez gratuitement. Projet complet dès {price}.", ur:"مفت شروع کریں۔ مکمل پروجیکٹ {price} سے۔" },
  "landing.priceBody": { ar:"ادفع فقط عندما تحتاج فتح مشروع كامل. لا اشتراك إجباري ولا تجديد تلقائي.", en:"Pay only when you need to unlock a full project. No mandatory subscription or auto-renewal.", tr:"Yalnızca tam projeyi açmak istediğinde öde. Zorunlu abonelik veya otomatik yenileme yok.", zh:"只在需要解锁完整项目时付费。无强制订阅、无自动续费。", hi:"पूरा प्रोजेक्ट अनलॉक करने पर ही भुगतान करें। कोई अनिवार्य सदस्यता या ऑटो-रिन्यूअल नहीं।", es:"Paga solo cuando necesites desbloquear un proyecto completo. Sin suscripción obligatoria ni renovación automática.", fr:"Payez uniquement lorsque vous souhaitez débloquer un projet complet. Aucun abonnement obligatoire ni renouvellement automatique.", ur:"صرف مکمل پروجیکٹ کھولنے پر ادائیگی کریں۔ لازمی سبسکرپشن یا خودکار تجدید نہیں۔" },
  "landing.perProject": { ar:"لكل مشروع", en:"per project", tr:"proje başına", zh:"每个项目", hi:"प्रति प्रोजेक्ट", es:"por proyecto", fr:"par projet", ur:"فی پروجیکٹ" },
