  "mission.valueFirst": { ar:"القيمة أولاً، الملف الشخصي لاحقاً", en:"Value first, profile later", tr:"Önce değer, profil sonra", zh:"先获得价值，再完善资料", hi:"पहले मूल्य, प्रोफ़ाइल बाद में", es:"Primero valor, perfil después", fr:"La valeur d’abord, le profil ensuite", ur:"پہلے قدر، پروفائل بعد میں" },
  "mission.valueFirstDesc": { ar:"لن نوقفك بإعداد طويل. ابدأ عملك أولاً، ثم خصّص الجامعة والتخصص عندما يفيد ذلك.", en:"No long setup wall. Start the work first, then add university and specialization when they improve the result.", tr:"Uzun kurulumla durdurmayız. Önce işe başla; üniversite ve bölümü fayda sağladığında ekle.", zh:"不会用冗长设置阻碍你。先开始任务，学校和专业在有帮助时再完善。", hi:"लंबे सेटअप से नहीं रोकेंगे। पहले काम शुरू करें; विश्वविद्यालय और विशेषज्ञता बाद में जोड़ें।", es:"No te frenamos con una configuración larga. Empieza y añade universidad y especialidad cuando aporte valor.", fr:"Pas de configuration interminable. Commencez le travail, puis ajoutez université et spécialité quand cela apporte de la valeur.", ur:"لمبی سیٹ اپ رکاوٹ نہیں۔ پہلے کام شروع کریں، یونیورسٹی اور تخصص بعد میں شامل کریں۔" },
  "mission.today": { ar:"مهمة اليوم", en:"Today’s mission", tr:"Bugünün görevi", zh:"今日任务", hi:"आज का मिशन", es:"Misión de hoy", fr:"Mission du jour", ur:"آج کا مشن" },
