  "mission.pressureCriticalDesc": { ar:"لديك {count} تسليمات خلال 7 أيام. رتبنا اليوم لتقليل مخاطر التزاحم.", en:"You have {count} deadlines within 7 days. Today is prioritized to reduce collision risk.", tr:"7 gün içinde {count} teslimin var. Bugün çakışma riskini azaltacak şekilde sıralandı.", zh:"未来 7 天有 {count} 个截止日期，今天的任务已按风险排序。", hi:"7 दिनों में {count} डेडलाइन हैं। आज की प्राथमिकताएँ टकराव कम करने के लिए व्यवस्थित हैं।", es:"Tienes {count} entregas en 7 días. Hoy está priorizado para reducir choques.", fr:"Vous avez {count} échéances sous 7 jours. La journée est priorisée pour limiter les collisions.", ur:"7 دن میں {count} ڈیڈ لائنز ہیں۔ آج کی ترجیحات ٹکراؤ کم کرنے کے لیے ترتیب دی گئی ہیں۔" },
  "mission.pressureBusyDesc": { ar:"لديك {count} تسليمات خلال 7 أيام. ركّز على الخطوات الأعلى أثراً.", en:"You have {count} deadline(s) within 7 days. Focus on the highest-impact steps.", tr:"7 gün içinde {count} teslim var. Etkisi en yüksek adımlara odaklan.", zh:"未来 7 天有 {count} 个截止日期，优先处理影响最大的步骤。", hi:"7 दिनों में {count} डेडलाइन हैं। सबसे प्रभावी कदमों पर ध्यान दें।", es:"Tienes {count} entrega(s) en 7 días. Prioriza lo de mayor impacto.", fr:"Vous avez {count} échéance(s) sous 7 jours. Concentrez-vous sur les étapes à fort impact.", ur:"7 دن میں {count} ڈیڈ لائنز ہیں۔ سب سے اہم اقدامات پر توجہ دیں۔" },
  "mission.pressureCalmDesc": { ar:"لا توجد تسليمات نهائية خلال 7 أيام؛ استثمر الوقت في تقدم عميق.", en:"No final deadline is due within 7 days; use the time for deeper progress.", tr:"7 gün içinde final teslim yok; zamanı derin ilerlemeye ayır.", zh:"未来 7 天没有最终截止日期，可以进行更深入的推进。", hi:"7 दिनों में कोई अंतिम डेडलाइन नहीं; समय का उपयोग गहरी प्रगति के लिए करें।", es:"No hay entregas finales en 7 días; aprovecha para avanzar en profundidad.", fr:"Aucune échéance finale sous 7 jours ; profitez-en pour avancer en profondeur.", ur:"7 دن میں کوئی حتمی ڈیڈ لائن نہیں؛ وقت کو گہری پیش رفت کے لیے استعمال کریں۔" },
  "mission.priorityReason": { ar:"أولوية محسوبة من الموعد وحالة العمل والمخاطر المسجلة", en:"Priority based on deadline, work state, and recorded risks", tr:"Öncelik teslim tarihi, iş durumu ve kayıtlı risklerden hesaplandı", zh:"优先级基于截止日期、工作状态和已记录风险", hi:"प्राथमिकता डेडलाइन, कार्य स्थिति और दर्ज जोखिमों पर आधारित है", es:"Prioridad calculada según fecha, estado del trabajo y riesgos registrados", fr:"Priorité calculée selon l’échéance, l’état du travail et les risques enregistrés", ur:"ترجیح ڈیڈ لائن، کام کی حالت اور درج شدہ خطرات پر مبنی ہے" },
  "mission.noPressure": { ar:"لا يوجد ضغط أكاديمي ظاهر الآن", en:"No visible academic pressure right now", tr:"Şu anda görünür akademik baskı yok", zh:"目前没有明显的学业压力", hi:"अभी कोई स्पष्ट शैक्षणिक दबाव नहीं", es:"No hay presión académica visible ahora", fr:"Aucune pression académique visible pour le moment", ur:"ابھی کوئی نمایاں تعلیمی دباؤ نہیں" },
  "mission.noPressureDesc": { ar:"ابدأ مشروعاً أو افتح Exam Coach لجلسة تعلم قصيرة.", en:"Start a project or open Exam Coach for a short learning session.", tr:"Bir proje başlat veya kısa bir öğrenme oturumu için Exam Coach’u aç.", zh:"开始一个项目，或打开 Exam Coach 进行短时学习。", hi:"प्रोजेक्ट शुरू करें या छोटी सीखने की सत्र के लिए Exam Coach खोलें।", es:"Inicia un proyecto o abre Exam Coach para una sesión corta.", fr:"Lancez un projet ou ouvrez Exam Coach pour une courte session.", ur:"پروجیکٹ شروع کریں یا مختصر سیکھنے کے سیشن کے لیے Exam Coach کھولیں۔" },
  "mission.brainTitle": { ar:"AcademicOS يتعلم كيف تتعلم", en:"AcademicOS learns how you learn", tr:"AcademicOS nasıl öğrendiğini öğrenir", zh:"AcademicOS 会学习你的学习方式", hi:"AcademicOS सीखता है कि आप कैसे सीखते हैं", es:"AcademicOS aprende cómo aprendes", fr:"AcademicOS apprend comment vous apprenez", ur:"AcademicOS سیکھتا ہے کہ آپ کیسے سیکھتے ہیں" },
  "mission.nextFocus": { ar:"تركيزك التالي", en:"Next focus", tr:"Sıradaki odak", zh:"下一重点", hi:"अगला फोकस", es:"Próximo foco", fr:"Prochain focus", ur:"اگلا فوکس" },
  "mission.nextFocusDesc": { ar:"هذه الأولوية مبنية فقط على مشاريعك وأدلة التعلم المحفوظة.", en:"This priority is based only on your projects and saved learning evidence.", tr:"Bu öncelik yalnızca projelerin ve kayıtlı öğrenme kanıtlarına dayanır.", zh:"此优先级仅基于你的项目和已保存的学习证据。", hi:"यह प्राथमिकता केवल आपके प्रोजेक्ट और सहेजे गए सीखने के प्रमाण पर आधारित है।", es:"Esta prioridad se basa solo en tus proyectos y evidencia de aprendizaje guardada.", fr:"Cette priorité repose uniquement sur vos projets et preuves d’apprentissage enregistrées.", ur:"یہ ترجیح صرف آپ کے پروجیکٹس اور محفوظ سیکھنے کے شواہد پر مبنی ہے۔" },
  "mission.brainEmpty": { ar:"كل مشروع ودليل تعلم ومناقشة يضيف إشارة جديدة إلى ما أتقنته وما يحتاج تدريباً أكثر.", en:"Every project, learning proof, and viva adds a signal about what you’ve mastered and what needs more practice.", tr:"Her proje, öğrenme kanıtı ve savunma, güçlü olduğun ve daha çok pratik gereken alanlara sinyal ekler.", zh:"每个项目、学习证据和答辩都会帮助识别你已掌握和仍需练习的内容。", hi:"हर प्रोजेक्ट, सीखने का प्रमाण और वाइवा बताता है कि क्या मजबूत है और क्या अभ्यास चाहता है।", es:"Cada proyecto, prueba de aprendizaje y defensa aporta señales de lo dominado y lo que requiere práctica.", fr:"Chaque projet, preuve d’apprentissage et soutenance ajoute un signal sur vos acquis et vos besoins de pratique.", ur:"ہر پروجیکٹ، سیکھنے کا ثبوت اور دفاع بتاتا ہے کہ کیا مضبوط ہے اور کہاں مزید مشق چاہیے۔" },
