  "mission.fileTooLarge": { ar:"الملف أكبر من 20MB.", en:"File is larger than 20MB.", tr:"Dosya 20MB’tan büyük.", zh:"文件大于 20MB。", hi:"फ़ाइल 20MB से बड़ी है।", es:"El archivo supera 20MB.", fr:"Le fichier dépasse 20 Mo.", ur:"فائل 20MB سے بڑی ہے۔" },
  "mission.compiledRescue": { ar:"قرأنا المسودة والتكليف وبنينا مسار إنقاذ قابلًا للتنفيذ.", en:"We read the draft and assignment and built an actionable rescue path.", tr:"Taslak ve ödevi okuyup uygulanabilir bir kurtarma yolu oluşturduk.", zh:"已读取草稿和作业，并建立可执行的修复路径。", hi:"ड्राफ्ट और असाइनमेंट पढ़कर कार्यान्वित सुधार मार्ग बनाया गया।", es:"Leímos el borrador y la tarea y creamos un plan de rescate accionable.", fr:"Nous avons lu le brouillon et le devoir et créé un parcours de sauvetage concret.", ur:"ڈرافٹ اور اسائنمنٹ پڑھ کر قابلِ عمل ریسکیو راستہ بنایا گیا۔" },
  "mission.compiledWrite": { ar:"قرأنا ما رفعته، فهمنا المطلوب وبنينا مساحة المشروع تلقائياً.", en:"We read what you uploaded, understood the requirements, and built the workspace automatically.", tr:"Yüklediğini okuyup gereksinimleri anladık ve çalışma alanını otomatik kurduk.", zh:"已读取上传内容、理解要求并自动建立工作空间。", hi:"अपलोड पढ़कर आवश्यकताएँ समझीं और कार्यक्षेत्र स्वतः बनाया।", es:"Leímos lo que subiste, entendimos los requisitos y creamos el espacio automáticamente.", fr:"Nous avons lu votre contenu, compris les exigences et créé automatiquement l’espace de travail.", ur:"اپ لوڈ شدہ مواد پڑھ کر تقاضے سمجھے اور ورک اسپیس خودکار بنایا۔" },
  "mission.error": { ar:"تعذر فهم ما رفعته. حاول مرة أخرى.", en:"We could not process what you provided. Try again.", tr:"Gönderdiğin içerik işlenemedi. Tekrar dene.", zh:"无法处理你提供的内容，请重试。", hi:"दिए गए इनपुट को संसाधित नहीं किया जा सका। फिर प्रयास करें।", es:"No pudimos procesar lo que enviaste. Inténtalo de nuevo.", fr:"Impossible de traiter ce que vous avez fourni. Réessayez.", ur:"آپ کا فراہم کردہ مواد پروسیس نہیں ہو سکا۔ دوبارہ کوشش کریں۔" },
  "mission.voiceUnsupported": { ar:"هذا المتصفح لا يدعم الإملاء الصوتي. اكتب أو ارفع الملف مباشرة.", en:"This browser does not support voice dictation. Type or upload instead.", tr:"Bu tarayıcı sesli dikteyi desteklemiyor. Yazın veya dosya yükleyin.", zh:"此浏览器不支持语音听写，请输入或上传文件。", hi:"यह ब्राउज़र वॉइस डिक्टेशन समर्थित नहीं करता। टाइप या अपलोड करें।", es:"Este navegador no admite dictado por voz. Escribe o sube un archivo.", fr:"Ce navigateur ne prend pas en charge la dictée vocale. Écrivez ou importez un fichier.", ur:"یہ براؤزر وائس ڈکٹیشن سپورٹ نہیں کرتا۔ لکھیں یا فائل اپ لوڈ کریں۔" },
  "mission.voiceError": { ar:"تعذر التقاط الصوت. حاول مرة أخرى أو اكتب طلبك.", en:"Could not capture audio. Try again or type your request.", tr:"Ses alınamadı. Tekrar deneyin veya isteğinizi yazın.", zh:"无法捕获语音，请重试或输入请求。", hi:"ऑडियो कैप्चर नहीं हुआ। फिर कोशिश करें या अनुरोध लिखें।", es:"No se pudo capturar el audio. Inténtalo o escribe tu solicitud.", fr:"Impossible de capter l’audio. Réessayez ou écrivez votre demande.", ur:"آڈیو کیپچر نہیں ہوا۔ دوبارہ کوشش کریں یا درخواست لکھیں۔" },
