  "upload2.rescueTitle": { ar:"لننقذ مشروعك", en:"Let’s rescue your project", tr:"Projenizi kurtaralım", zh:"来拯救你的项目", hi:"आपके प्रोजेक्ट को सुधारें", es:"Rescatemos tu proyecto", fr:"Sauvons votre projet", ur:"آپ کا پروجیکٹ بچائیں" },
  "upload2.writeTitle": { ar:"لنبدأ مشروعك", en:"Let’s build your project", tr:"Projenizi oluşturalım", zh:"开始你的项目", hi:"आपका प्रोजेक्ट शुरू करें", es:"Empecemos tu proyecto", fr:"Construisons votre projet", ur:"آپ کا پروجیکٹ شروع کریں" },
  "upload2.desc": { ar:"ارفع ما لديك. نفهم المطلوب، نبني خطة واضحة ثم ننقلك مباشرة إلى مساحة المشروع.", en:"Upload what you have. We understand the requirements, build a clear plan, then take you straight to the workspace.", tr:"Elinizdekileri yükleyin. Gereksinimleri anlayıp net bir plan kurar ve doğrudan çalışma alanına götürürüz.", zh:"上传现有材料。我们会理解要求、建立清晰计划并直接进入工作空间。", hi:"जो है अपलोड करें। हम आवश्यकताएँ समझकर स्पष्ट योजना बनाते हैं और सीधे कार्यक्षेत्र में ले जाते हैं।", es:"Sube lo que tengas. Entendemos los requisitos, creamos un plan claro y te llevamos al espacio de trabajo.", fr:"Importez ce que vous avez. Nous comprenons les exigences, créons un plan clair puis ouvrons l’espace de travail.", ur:"جو کچھ ہے اپ لوڈ کریں۔ ہم تقاضے سمجھ کر واضح منصوبہ بناتے ہیں اور سیدھا ورک اسپیس کھولتے ہیں۔" },
  "upload2.taskType": { ar:"نوع المهمة", en:"Task type", tr:"Görev türü", zh:"任务类型", hi:"कार्य प्रकार", es:"Tipo de tarea", fr:"Type de tâche", ur:"کام کی قسم" },
