  "prof2.firstCourseDesc": { ar:"اختر السياسة وانسخ الرابط؛ هذا كل ما تحتاجه للبدء.", en:"Choose the policy and copy the link; that’s all you need to start.", tr:"Politikayı seçin ve bağlantıyı kopyalayın; başlamak için gereken bu kadar.", zh:"选择政策并复制链接；开始只需这些。", hi:"नीति चुनें और लिंक कॉपी करें; शुरुआत के लिए इतना ही।", es:"Elige la política y copia el enlace; eso basta para empezar.", fr:"Choisissez la politique et copiez le lien ; cela suffit pour commencer.", ur:"پالیسی منتخب کریں اور لنک کاپی کریں؛ آغاز کے لیے بس یہی چاہیے۔" },
  "prof2.policy1": { ar:"خطة وفهم فقط", en:"Plan and understand only", tr:"Yalnızca plan ve anlama", zh:"仅规划与理解", hi:"केवल योजना और समझ", es:"Solo plan y comprensión", fr:"Plan et compréhension uniquement", ur:"صرف منصوبہ اور سمجھ" },
  "prof2.policy1Desc": { ar:"يسمح بالفهم والأسئلة وبناء الخطة، ويكتب الطالب نص التسليم بنفسه.", en:"Allows understanding, questions, and planning; the student writes the submission themselves.", tr:"Anlama, soru ve planlamaya izin verir; teslim metnini öğrenci yazar.", zh:"允许理解、提问和规划；最终提交文本由学生自行撰写。", hi:"समझ, प्रश्न और योजना की अनुमति; जमा करने का टेक्स्ट छात्र स्वयं लिखता है।", es:"Permite comprender, preguntar y planificar; el estudiante redacta la entrega.", fr:"Autorise compréhension, questions et planification ; l’étudiant rédige le rendu.", ur:"سمجھ، سوال اور منصوبہ بندی کی اجازت؛ جمع کرانے کا متن طالب خود لکھتا ہے۔" },
  "prof2.policy2": { ar:"مراجعة وتحسين", en:"Review and improve", tr:"İncele ve iyileştir", zh:"审阅与改进", hi:"समीक्षा और सुधार", es:"Revisar y mejorar", fr:"Réviser et améliorer", ur:"جائزہ اور بہتری" },
  "prof2.policy2Desc": { ar:"يسمح بالمراجعة والشرح واقتراح التحسينات مع بقاء الصياغة النهائية للطالب.", en:"Allows review, explanation, and improvement suggestions while final wording remains the student’s.", tr:"İnceleme, açıklama ve iyileştirme önerilerine izin verir; son ifade öğrenciye aittir.", zh:"允许审阅、解释和改进建议，最终措辞仍由学生完成。", hi:"समीक्षा, व्याख्या और सुधार सुझाव की अनुमति; अंतिम शब्द छात्र के।", es:"Permite revisar, explicar y sugerir mejoras; la redacción final sigue siendo del estudiante.", fr:"Autorise révision, explication et suggestions ; la formulation finale reste celle de l’étudiant.", ur:"جائزہ، وضاحت اور بہتری کی تجویز؛ حتمی تحریر طالب کی رہتی ہے۔" },
  "prof2.policy4": { ar:"مسودة معلنة", en:"Disclosed draft", tr:"Beyanlı taslak", zh:"披露式草稿", hi:"घोषित ड्राफ्ट", es:"Borrador declarado", fr:"Brouillon déclaré", ur:"اعلان شدہ ڈرافٹ" },
  "prof2.policy4Desc": { ar:"يسمح بمسودة كاملة بشرط الإفصاح والتحقق من المصادر وفهم الطالب لكل جزء.", en:"Allows a full draft with disclosure, source verification, and student understanding of every part.", tr:"Beyan, kaynak doğrulama ve öğrencinin her bölümü anlaması koşuluyla tam taslağa izin verir.", zh:"允许完整草稿，但要求披露、来源验证并确保学生理解每一部分。", hi:"पूर्ण ड्राफ्ट की अनुमति, बशर्ते प्रकटीकरण, स्रोत सत्यापन और हर भाग की छात्र समझ हो।", es:"Permite borrador completo con divulgación, verificación de fuentes y comprensión de cada parte.", fr:"Autorise un brouillon complet avec divulgation, vérification des sources et compréhension de chaque partie.", ur:"مکمل ڈرافٹ کی اجازت، بشرط اعلان، ذرائع کی تصدیق اور ہر حصے کی طالب سمجھ۔" },
