  "prof2.allowViva": { ar:"تدريب المناقشة", en:"Viva practice", tr:"Savunma pratiği", zh:"答辩训练", hi:"वाइवा अभ्यास", es:"Práctica de defensa", fr:"Entraînement à la soutenance", ur:"دفاعی مشق" },
  "prof2.blockSubmit": { ar:"صياغة نص التسليم", en:"Writing the submission text", tr:"Teslim metnini yazma", zh:"撰写提交文本", hi:"जमा करने का टेक्स्ट लिखना", es:"Redactar el texto de entrega", fr:"Rédiger le texte à rendre", ur:"جمع کرانے کا متن لکھنا" },
