  "prof2.blockFullSubmission": { ar:"توليد تسليم كامل", en:"Generating a full submission", tr:"Tam teslim oluşturma", zh:"生成完整提交稿", hi:"पूर्ण जमा तैयार करना", es:"Generar una entrega completa", fr:"Générer un rendu complet", ur:"مکمل جمع کرانا تیار کرنا" },
  "prof2.blockFakeData": { ar:"اختلاق البيانات والمصادر", en:"Fabricating data or sources", tr:"Veri veya kaynak uydurma", zh:"虚构数据或来源", hi:"डेटा या स्रोत गढ़ना", es:"Inventar datos o fuentes", fr:"Inventer des données ou sources", ur:"ڈیٹا یا ذرائع گھڑنا" },
