  "learn.todaySession": { ar:"جلسة اليوم", en:"Today’s session", tr:"Bugünkü oturum", zh:"今日学习", hi:"आज का सत्र", es:"Sesión de hoy", fr:"Session du jour", ur:"آج کا سیشن" },
  "learn.focusReason": { ar:"أولوية مبنية على أدلة التعلم المسجلة ونقاط المراجعة الحالية.", en:"Priority based on recorded learning evidence and current review needs.", tr:"Kayıtlı öğrenme kanıtı ve mevcut tekrar ihtiyaçlarına dayalı öncelik.", zh:"优先级基于已记录的学习证据和当前复习需求。", hi:"रिकॉर्ड किए गए सीखने के प्रमाण और वर्तमान समीक्षा जरूरतों पर आधारित प्राथमिकता।", es:"Prioridad basada en la evidencia de aprendizaje registrada y las necesidades actuales de repaso.", fr:"Priorité fondée sur les preuves d'apprentissage enregistrées et les besoins actuels de révision.", ur:"ترجیح محفوظ تعلیمی ثبوت اور موجودہ جائزے کی ضرورت پر مبنی ہے۔" },
  "learn.startOneMaterial": { ar:"ابدأ بمادة واحدة فقط", en:"Start with one source", tr:"Tek bir materyalle başlayın", zh:"先从一份材料开始", hi:"एक सामग्री से शुरू करें", es:"Empieza con un solo material", fr:"Commencez avec un seul support", ur:"ایک ہی مواد سے شروع کریں" },
  "learn.startOneMaterialDesc": { ar:"بعد أول شرح وحل ومناقشة، يبدأ Learning Brain بتحديد ما أتقنته وما يحتاج مراجعة أكثر.", en:"After your first explanation, solution, and viva, Learning Brain starts identifying what you know and what needs more review.", tr:"İlk açıklama, çözüm ve sözlüden sonra Learning Brain bildiklerinizi ve daha fazla tekrar gerektirenleri belirlemeye başlar.", zh:"完成第一次讲解、解题和答辩后，Learning Brain 会开始识别你已掌握和需要加强复习的内容。", hi:"पहली व्याख्या, समाधान और वाइवा के बाद Learning Brain पहचानना शुरू करता है कि आप क्या जानते हैं और क्या अधिक समीक्षा चाहता है।", es:"Tras la primera explicación, solución y defensa, Learning Brain empieza a identificar lo que dominas y lo que necesita más repaso.", fr:"Après la première explication, résolution et soutenance, Learning Brain commence à identifier ce qui est acquis et ce qui doit être davantage révisé.", ur:"پہلی وضاحت، حل اور وائیوا کے بعد Learning Brain بتانا شروع کرتا ہے کہ کیا آتا ہے اور کس چیز کو مزید دہرانا ہے۔" },
