  "control.fairUseTitle": { ar:"درع الاستخدام العادل", en:"Fair-use protection", tr:"Adil kullanım koruması", zh:"公平使用保护", hi:"निष्पक्ष उपयोग सुरक्षा", es:"Protección de uso justo", fr:"Protection d’usage équitable", ur:"منصفانہ استعمال کا تحفظ" },
  "control.fairUseDesc": { ar:"يحمي المعاينة المجانية من تعدد الحسابات عبر إشارات مجمعة ومحافظة على الخصوصية: تحقق البريد، App Check، تثبيت المتصفح، بصمة جهاز تقريبية، وسرعة الشبكة. لا توجد قراءة MAC ولا نعتمد على IP وحده.", en:"Protects free previews from multi-account abuse using layered, privacy-preserving signals: verified email, App Check, browser installation, a coarse device cohort, and network velocity. No MAC address is read, and IP alone never decides.", tr:"Ücretsiz önizlemeleri çoklu hesap kötüye kullanımına karşı; doğrulanmış e-posta, App Check, tarayıcı kurulumu, kaba cihaz grubu ve ağ hızı sinyalleriyle korur. MAC adresi okunmaz ve IP tek başına karar vermez.", zh:"通过分层且保护隐私的信号防止多账号滥用免费预览：已验证邮箱、App Check、浏览器安装标识、粗粒度设备群组和网络速度。不会读取 MAC，也不会仅凭 IP 决策。", hi:"मुफ़्त प्रीव्यू को बहु-खाता दुरुपयोग से बचाने के लिए सत्यापित ईमेल, App Check, ब्राउज़र इंस्टॉलेशन, मोटे डिवाइस समूह और नेटवर्क वेग जैसे गोपनीयता-संरक्षित संकेत उपयोग होते हैं। MAC नहीं पढ़ा जाता और IP अकेले निर्णय नहीं करता।", es:"Protege las vistas previas gratuitas del abuso con múltiples cuentas mediante señales por capas y respetuosas con la privacidad: correo verificado, App Check, instalación del navegador, cohorte aproximada de dispositivo y velocidad de red. No se lee la MAC y la IP nunca decide por sí sola.", fr:"Protège les aperçus gratuits contre les comptes multiples grâce à des signaux en couches respectueux de la vie privée : e-mail vérifié, App Check, installation du navigateur, cohorte d’appareil approximative et vélocité réseau. Aucune adresse MAC n’est lue et l’IP ne décide jamais seule.", ur:"مفت پری ویو کو متعدد اکاؤنٹس کے غلط استعمال سے بچانے کے لیے تصدیق شدہ ای میل، App Check، براؤزر انسٹالیشن، عمومی ڈیوائس گروپ اور نیٹ ورک رفتار جیسے پرائیویسی محفوظ اشارے استعمال ہوتے ہیں۔ MAC نہیں پڑھا جاتا اور IP اکیلا فیصلہ نہیں کرتا۔" },
  "control.noMac": { ar:"لا MAC · قرار متعدد الإشارات", en:"No MAC · multi-signal decision", tr:"MAC yok · çoklu sinyal kararı", zh:"不读取 MAC · 多信号决策", hi:"MAC नहीं · बहु-संकेत निर्णय", es:"Sin MAC · decisión multiseñal", fr:"Sans MAC · décision multi-signal", ur:"MAC نہیں · متعدد اشاروں کا فیصلہ" },
  "control.fairUseReviewed": { ar:"أحداث ثقة راجعت", en:"Trust events reviewed", tr:"İncelenen güven olayları", zh:"已审查信任事件", hi:"समीक्षित ट्रस्ट घटनाएँ", es:"Eventos de confianza revisados", fr:"Événements de confiance examinés", ur:"جائزہ شدہ ٹرسٹ ایونٹس" },
  "control.fairUseDenied": { ar:"امتيازات مجانية موقوفة", en:"Free benefits blocked", tr:"Engellenen ücretsiz haklar", zh:"已拦截免费权益", hi:"ब्लॉक किए मुफ़्त लाभ", es:"Beneficios gratuitos bloqueados", fr:"Avantages gratuits bloqués", ur:"روکے گئے مفت فوائد" },
  "control.fairUseStepUp": { ar:"إشارات تحتاج تحققًا إضافيًا", en:"Step-up signals", tr:"Ek doğrulama sinyalleri", zh:"需增强验证的信号", hi:"अतिरिक्त सत्यापन संकेत", es:"Señales de verificación adicional", fr:"Signaux de vérification renforcée", ur:"اضافی تصدیق کے اشارے" },
  "control.fairUseDevices": { ar:"أجهزة متعددة الحسابات", en:"Multi-account devices", tr:"Çok hesaplı cihazlar", zh:"多账号设备", hi:"बहु-खाता डिवाइस", es:"Dispositivos multicuenta", fr:"Appareils multi-comptes", ur:"متعدد اکاؤنٹ ڈیوائسز" },

  "layout.verifyEmailTitle": { ar:"تحقق من بريدك.", en:"Verify your email.", tr:"E-postanızı doğrulayın.", zh:"验证你的邮箱。", hi:"अपना ईमेल सत्यापित करें।", es:"Verifica tu correo.", fr:"Vérifiez votre e-mail.", ur:"اپنی ای میل کی تصدیق کریں۔" },
  "layout.verifyEmailDesc": { ar:"يمكنك استكشاف المنصة الآن، لكن الامتيازات المجانية المكلفة بالذكاء الاصطناعي تُفتح بعد التحقق لحماية الاستخدام العادل.", en:"You can explore now, but costly free AI benefits unlock after verification to protect fair use.", tr:"Şimdi platformu keşfedebilirsiniz; maliyetli ücretsiz AI hakları adil kullanımı korumak için doğrulamadan sonra açılır.", zh:"你现在可以浏览平台，但高成本的免费 AI 权益会在邮箱验证后解锁，以保护公平使用。", hi:"आप अभी प्लेटफ़ॉर्म देख सकते हैं, लेकिन निष्पक्ष उपयोग की सुरक्षा के लिए महंगे मुफ़्त AI लाभ सत्यापन के बाद खुलते हैं।", es:"Puedes explorar ahora, pero los beneficios gratuitos de IA de mayor coste se activan tras verificar el correo para proteger el uso justo.", fr:"Vous pouvez explorer la plateforme maintenant, mais les avantages IA gratuits coûteux s’activent après vérification afin de protéger l’usage équitable.", ur:"آپ ابھی پلیٹ فارم دیکھ سکتے ہیں، مگر مہنگے مفت AI فوائد منصفانہ استعمال کے تحفظ کے لیے تصدیق کے بعد کھلتے ہیں۔" },
  "layout.resendVerification": { ar:"أرسل رابط التحقق", en:"Send verification link", tr:"Doğrulama bağlantısı gönder", zh:"发送验证链接", hi:"सत्यापन लिंक भेजें", es:"Enviar enlace de verificación", fr:"Envoyer le lien de vérification", ur:"تصدیقی لنک بھیجیں" },
  "layout.verificationSent": { ar:"تم الإرسال", en:"Sent", tr:"Gönderildi", zh:"已发送", hi:"भेजा गया", es:"Enviado", fr:"Envoyé", ur:"بھیج دیا" },
