  // ---- Requirement Truth Matrix ----
  "req.title": { ar:"مصفوفة ما طلبه التكليف فعلًا", en:"What the assignment actually asks", tr:"Ödevin gerçekten istediği şey", zh:"作业真正要求什么", hi:"असाइनमेंट वास्तव में क्या मांगता है", es:"Lo que realmente pide la tarea", fr:"Ce que le devoir demande réellement", ur:"اسائنمنٹ حقیقت میں کیا مانگتا ہے" },
  "req.description": { ar:"لا نضيف شروطًا افتراضية. كل صف مأخوذ من Project DNA المستخرج من تكليفك، مع مستوى الثقة والمصدر عند توفره.", en:"No default requirements are invented. Every row comes from Project DNA extracted from your assignment, with confidence and source when available.", tr:"Varsayılan koşullar uydurulmaz. Her satır ödevinizden çıkarılan Project DNA’dan gelir; varsa güven düzeyi ve kaynak gösterilir.", zh:"不会虚构默认要求。每一行都来自从作业中提取的 Project DNA，并在可用时显示置信度和来源。", hi:"कोई डिफ़ॉल्ट शर्त गढ़ी नहीं जाती। हर पंक्ति आपके असाइनमेंट से निकले Project DNA से आती है, और उपलब्ध होने पर भरोसे का स्तर व स्रोत दिखते हैं।", es:"No inventamos requisitos predeterminados. Cada fila proviene del Project DNA extraído de tu tarea, con nivel de confianza y fuente cuando existen.", fr:"Aucune exigence par défaut n’est inventée. Chaque ligne vient du Project DNA extrait de votre devoir, avec niveau de confiance et source lorsqu’ils existent.", ur:"کوئی فرضی شرط نہیں بنائی جاتی۔ ہر قطار آپ کے اسائنمنٹ سے اخذ شدہ Project DNA سے آتی ہے، اور دستیاب ہونے پر اعتماد اور ذریعہ دکھایا جاتا ہے۔" },
  "req.extracted": { ar:"شروط مستخرجة", en:"Extracted requirements", tr:"Çıkarılan koşullar", zh:"提取的要求", hi:"निकाली गई आवश्यकताएँ", es:"Requisitos extraídos", fr:"Exigences extraites", ur:"اخذ شدہ تقاضے" },
  "req.rubricCriteria": { ar:"معايير Rubric", en:"Rubric criteria", tr:"Rubrik ölçütleri", zh:"评分标准条目", hi:"रूब्रिक मानदंड", es:"Criterios de rúbrica", fr:"Critères de grille", ur:"روبرک معیار" },
  "req.all": { ar:"كل الشروط", en:"All requirements", tr:"Tüm koşullar", zh:"全部要求", hi:"सभी आवश्यकताएँ", es:"Todos los requisitos", fr:"Toutes les exigences", ur:"تمام تقاضے" },
  "req.noDetail": { ar:"لم يُستخرج وصف تفصيلي لهذا الشرط.", en:"No detailed description was extracted for this requirement.", tr:"Bu koşul için ayrıntılı açıklama çıkarılmadı.", zh:"未提取到此要求的详细说明。", hi:"इस आवश्यकता का विस्तृत विवरण नहीं निकाला गया।", es:"No se extrajo una descripción detallada de este requisito.", fr:"Aucune description détaillée n’a été extraite pour cette exigence.", ur:"اس تقاضے کی تفصیلی وضاحت اخذ نہیں ہوئی۔" },
  "req.source": { ar:"المصدر داخل التكليف", en:"Source in assignment", tr:"Ödevdeki kaynak", zh:"作业中的来源", hi:"असाइनमेंट में स्रोत", es:"Fuente en la tarea", fr:"Source dans le devoir", ur:"اسائنمنٹ میں ذریعہ" },
  "req.emptyCategory": { ar:"لا توجد شروط ضمن هذا التصنيف.", en:"No requirements in this category.", tr:"Bu kategoride koşul yok.", zh:"此类别没有要求。", hi:"इस श्रेणी में कोई आवश्यकता नहीं है।", es:"No hay requisitos en esta categoría.", fr:"Aucune exigence dans cette catégorie.", ur:"اس زمرے میں کوئی تقاضہ نہیں۔" },
  "req.emptyAll": { ar:"لم يستخرج النظام شروطًا صريحة بعد. ارجع إلى التكليف الأصلي أو أعد تحليله بدل الاعتماد على شروط افتراضية.", en:"No explicit requirements have been extracted yet. Review or re-analyze the original assignment instead of relying on defaults.", tr:"Henüz açık koşullar çıkarılmadı. Varsayımlara güvenmek yerine özgün ödevi inceleyin veya yeniden analiz edin.", zh:"尚未提取到明确要求。请查看或重新分析原始作业，而不是依赖默认值。", hi:"अभी स्पष्ट आवश्यकताएँ नहीं निकली हैं। डिफ़ॉल्ट पर निर्भर होने के बजाय मूल असाइनमेंट की समीक्षा या पुनः विश्लेषण करें।", es:"Aún no se extrajeron requisitos explícitos. Revisa o vuelve a analizar la tarea original en lugar de depender de valores predeterminados.", fr:"Aucune exigence explicite n’a encore été extraite. Examinez ou réanalysez le devoir original plutôt que de vous fier à des valeurs par défaut.", ur:"ابھی واضح تقاضے اخذ نہیں ہوئے۔ فرضی ڈیفالٹ پر انحصار کرنے کے بجائے اصل اسائنمنٹ کا جائزہ یا دوبارہ تجزیہ کریں۔" },
  "req.covered": { ar:"مغطى بأدلة", en:"Evidence covered", tr:"Kanıtla karşılandı", zh:"有证据覆盖", hi:"साक्ष्य से कवर", es:"Cubierto con evidencia", fr:"Couvert par des preuves", ur:"ثبوت سے احاطہ" },
  "req.partial": { ar:"جزئي/يحتاج مراجعة", en:"Partial / review", tr:"Kısmi / inceleme", zh:"部分 / 需复核", hi:"आंशिक / समीक्षा", es:"Parcial / revisar", fr:"Partiel / à revoir", ur:"جزوی / جائزہ" },
