  // ---- Integrity Guardian & Evidence Capsule ----
  "common.close": { ar:"إغلاق", en:"Close", tr:"Kapat", zh:"关闭", hi:"बंद करें", es:"Cerrar", fr:"Fermer", ur:"بند کریں" },
  "common.print": { ar:"طباعة", en:"Print", tr:"Yazdır", zh:"打印", hi:"प्रिंट", es:"Imprimir", fr:"Imprimer", ur:"پرنٹ" },
  "common.copy": { ar:"نسخ", en:"Copy", tr:"Kopyala", zh:"复制", hi:"कॉपी", es:"Copiar", fr:"Copier", ur:"کاپی" },
  "common.copied": { ar:"تم النسخ", en:"Copied", tr:"Kopyalandı", zh:"已复制", hi:"कॉपी हो गया", es:"Copiado", fr:"Copié", ur:"کاپی ہوگیا" },
  "integrity.title": { ar:"فاحص الأسلوب والنزاهة", en:"Style & Integrity Guardian", tr:"Üslup ve Dürüstlük Denetçisi", zh:"风格与学术诚信守护器", hi:"शैली और अकादमिक ईमानदारी जाँच", es:"Guardián de estilo e integridad", fr:"Gardien du style et de l’intégrité", ur:"اسلوب اور علمی دیانت جانچ" },
  "integrity.description": { ar:"يراجع الصياغة النمطية، رتابة الجمل، الادعاءات الرقمية التي تحتاج سنداً، وإشارات المراجع التي تحتاج تحققاً. لا يدّعي تحديد من كتب النص ولا ينتحل اسم أي كاشف خارجي.", en:"Reviews formulaic phrasing, sentence rhythm, quantitative claims that need evidence, and citations that need verification. It does not claim to identify who wrote the text or impersonate any external detector.", tr:"Kalıplaşmış ifadeleri, cümle ritmini, kanıt gerektiren sayısal iddiaları ve doğrulanması gereken atıfları inceler. Metni kimin yazdığını belirlediğini iddia etmez ve harici bir tespit aracını taklit etmez.", zh:"检查模板化措辞、句子节奏、需要证据支持的数字性主张，以及需要核验的引用。它不会声称判断文本由谁撰写，也不会冒充任何外部检测工具。", hi:"फ़ॉर्मूलाबद्ध भाषा, वाक्य लय, प्रमाण चाहने वाले संख्यात्मक दावों और सत्यापन योग्य संदर्भों की समीक्षा करता है। यह लेखक की पहचान करने या किसी बाहरी डिटेक्टर का दावा नहीं करता।", es:"Revisa lenguaje formular, ritmo de frases, afirmaciones cuantitativas que requieren evidencia y citas que necesitan verificación. No pretende identificar quién escribió el texto ni hacerse pasar por detectores externos.", fr:"Analyse les formulations stéréotypées, le rythme des phrases, les affirmations quantitatives nécessitant des preuves et les citations à vérifier. Il ne prétend pas identifier l’auteur ni se faire passer pour un détecteur externe.", ur:"فارمولہ نما عبارت، جملوں کی لے، ثبوت مانگنے والے عددی دعوے اور تصدیق طلب حوالہ جات کا جائزہ لیتا ہے۔ یہ مصنف کی شناخت یا کسی بیرونی ڈیٹیکٹر کی نقالی کا دعویٰ نہیں کرتا۔" },
  "integrity.scopeTitle": { ar:"افحص المشروع كله أو فقرة محددة", en:"Check the whole project or a specific passage", tr:"Tüm projeyi veya belirli bir bölümü inceleyin", zh:"检查整个项目或特定段落", hi:"पूरे प्रोजेक्ट या किसी विशेष अंश की जाँच करें", es:"Revisa todo el proyecto o un fragmento concreto", fr:"Analysez tout le projet ou un passage précis", ur:"پورا پروجیکٹ یا مخصوص اقتباس جانچیں" },
