  "integrity.trustFirst": { ar:"الثقة قبل النتيجة", en:"Trust before the score", tr:"Skordan önce güven", zh:"分数之前，先要可信", hi:"स्कोर से पहले भरोसा", es:"Confianza antes que puntuación", fr:"La confiance avant le score", ur:"اسکور سے پہلے اعتماد" },
  "integrity.trustDescription": { ar:"هذا الفاحص لا يعطي وعداً زائفاً بأن النص «بشري 100%». هدفه جعل النص أوضح، الأدلة أقوى، والمخاطر الأكاديمية مرئية قبل التسليم.", en:"This checker never promises that a text is “100% human.” Its purpose is to make writing clearer, evidence stronger, and academic risks visible before submission.", tr:"Bu denetleyici bir metnin “%100 insan yazımı” olduğunu vaat etmez. Amaç; metni netleştirmek, kanıtı güçlendirmek ve akademik riskleri teslimden önce görünür kılmaktır.", zh:"本工具不会虚假承诺文本“100% 由人类撰写”。它的目标是让表达更清晰、证据更扎实，并在提交前暴露学术风险。", hi:"यह जाँच कभी यह झूठा वादा नहीं करती कि पाठ “100% मानव-लिखित” है। इसका उद्देश्य लेखन को स्पष्ट, प्रमाण को मजबूत और जमा करने से पहले अकादमिक जोखिमों को दृश्यमान बनाना है।", es:"Este revisor nunca promete falsamente que un texto sea “100% humano”. Su objetivo es aclarar la escritura, fortalecer la evidencia y hacer visibles los riesgos académicos antes de entregar.", fr:"Cet outil ne promet jamais qu’un texte est « 100 % humain ». Il vise à clarifier l’écriture, renforcer les preuves et rendre visibles les risques académiques avant la remise.", ur:"یہ جانچ کبھی یہ جھوٹا وعدہ نہیں کرتی کہ متن “100٪ انسانی” ہے۔ مقصد عبارت کو واضح، ثبوت کو مضبوط اور جمع کرانے سے پہلے علمی خطرات کو نمایاں کرنا ہے۔" },
  "integrity.errorAnalyze": { ar:"تعذر تشغيل فاحص الأسلوب والنزاهة.", en:"Could not run the style and integrity review.", tr:"Üslup ve dürüstlük incelemesi çalıştırılamadı.", zh:"无法运行风格与诚信审查。", hi:"शैली और ईमानदारी समीक्षा नहीं चल सकी।", es:"No se pudo ejecutar la revisión de estilo e integridad.", fr:"Impossible d’exécuter la revue de style et d’intégrité.", ur:"اسلوب اور دیانت کا جائزہ نہیں چل سکا۔" },
